(() => {
'use strict';
const C=window.HAYAH_CONTENT, S=window.HayahStore, root=document.getElementById('app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>new Intl.NumberFormat('ar-EG').format(x), date=x=>new Intl.DateTimeFormat('ar-EG',{day:'numeric',month:'long'}).format(new Date(x));
const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
let ui={screen:S.loadError?'load-error':S.data.characterId?'map':S.data.profile?'character':'welcome',jid:S.data.activeJourneyId,stageId:null,step:'activity',promptId:null,returnTo:null};
let selectedCharacter=S.data.characterId, nickname=S.data.profile?.name||'', activity={}, activityDirty=false;
const draftCache={}, failedDrafts=new Set(); let video=null, videoEnd=0, videoReady=false, videoComplete=false, frameId=null, lastMediaSave=0, lastObserved=0, mediaWasPlaying=false, mediaFailed=false;
const journey=()=>C.journeys.find(j=>j.id===ui.jid), stage=()=>journey()?.stages.find(s=>s.id===ui.stageId), progress=()=>S.data.journeys[ui.jid];
const icon=(name='leaf')=>{const paths={leaf:'<path d="M20 4C9 3 3 7 4 14c1 8 14 8 16-10ZM5 20 16 9"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>',book:'<path d="M12 5C9 2 4 3 3 4v15c3-2 6-2 9 1 3-3 6-3 9-1V4c-3-2-6-2-9 1Zm0 0v15"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3 6 0 1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z"/>',back:'<path d="m9 5 7 7-7 7"/>',arrow:'<path d="M19 12H5m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 1 1 8 0v3"/>',heart:'<path d="M12 21S2 15 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 13-10 13Z"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',door:'<path d="M4 22V11a8 8 0 0 1 16 0v11M8 22V11a4 4 0 0 1 8 0v11m-3-8v2"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.leaf}</svg>`;};
function button(label,act,value='',kind='primary',extra=''){return `<button class="${kind}" data-act="${esc(act)}" data-value="${esc(value)}" ${extra}>${label}</button>`;}
function doll(id=S.data.characterId,cls='doll'){const c=C.characters.find(x=>x.id===id);return c?`<img class="${cls}" src="${c.asset}" alt="${esc(c.label)}" draggable="false">`:'';}
function garden(){return `<svg class="garden-bg" viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path d="M0 278Q80 224 170 274T400 261V300H0Z" fill="#D8E5BA"/><path d="M25 255V115a70 70 0 0 1 140 0M235 255V115a70 70 0 0 1 140 0" fill="none" stroke="#E4D0A9" stroke-width="10"/><path d="M0 28Q60 50 100 3M290 0Q320 45 400 35" fill="none" stroke="#75915C" stroke-width="4"/>${[[30,30],[62,32],[96,11],[322,27],[353,38],[380,29],[22,263],[364,272]].map(([x,y])=>`<g transform="translate(${x} ${y})"><path d="M-3 0Q-22-22-25-4Q-9 12-3 0M3 0Q25-18 24-2Q9 11 3 0" fill="#7D9F61"/><g fill="#FFFDF6"><ellipse rx="5" ry="12" cy="-7"/><ellipse rx="5" ry="12" cy="-7" transform="rotate(72)"/><ellipse rx="5" ry="12" cy="-7" transform="rotate(144)"/><ellipse rx="5" ry="12" cy="-7" transform="rotate(216)"/><ellipse rx="5" ry="12" cy="-7" transform="rotate(288)"/></g><circle r="4" fill="#D8AC4E"/></g>`).join('')}</svg>`;}
function hero(both=false){return `<div class="hero">${garden()}${both?doll('boy')+doll('girl'):doll()}</div>`;}
function doorArt(theme){return `<svg class="door-svg" viewBox="0 0 90 140" aria-hidden="true"><path d="M8 132V49a37 37 0 0 1 74 0v83Z" fill="#FBDDBC" stroke="#C6A47F" stroke-width="2"/><path d="M18 132V50a27 27 0 0 1 54 0v82Z" fill="${theme==='sky'?'#AFCDDD':'#B9CCA2'}"/><path d="M26 130V51a19 19 0 0 1 38 0v79Z" fill="#FFFCF7"/><path d="m64 50-29 13v67h29Z" fill="${theme==='sky'?'#193D59':'#35644A'}"/><circle cx="54" cy="90" r="3" fill="#FBDDBC"/><path d="M3 135h84" stroke="#C6A47F" stroke-width="5" stroke-linecap="round"/><path d="M5 41Q-4 15 8 8M78 27Q91 14 86 4" fill="none" stroke="#75915C" stroke-width="3"/></svg>`;}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,6500);}
function save(change){if(S.commit(change))return true;toast('لم نقدر نحفظ على الجهاز. اختياراتك ما زالت هنا؛ جرّب مرة أخرى.');return false;}
function modal(title,text,action,label='متابعة'){const d=document.getElementById('dialog');d.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2><p>${esc(text)}</p><div class="actions">${button('رجوع','close-dialog','','secondary','autofocus')}${button(esc(label),'confirm','','primary')}</div>`;d.confirmAction=action;d.showModal();}
function closeModal(){document.getElementById('dialog').close();}
function retryDrafts(){let ok=true;for(const id of [...failedDrafts]){if(S.commit(d=>d.drafts[id]=draftCache[id]))failedDrafts.delete(id);else ok=false;}if(activityDirty){if(S.commit(d=>d.journeys[ui.jid].activities[ui.stageId]=S.clone(activity)))activityDirty=false;else ok=false;}return ok;}
function navigate(screen,params={},bypass=false){
  if(!bypass&&(failedDrafts.size||activityDirty)){
    modal('كتابتك لم تُحفظ بعد','تقدر ترجع للكتابة أو تحاول الحفظ قبل المغادرة.',()=>{if(retryDrafts()){closeModal();navigate(screen,params,true);}else toast('ما زال الحفظ متعذرًا. كتابتك موجودة هنا.');},'حفظ ومتابعة');
    const d=document.getElementById('dialog');d.querySelector('.actions').insertAdjacentHTML('beforeend',button('أترك التغييرات غير المحفوظة','discard-edits','','quiet danger'));d.discardAction=()=>{for(const id of failedDrafts)delete draftCache[id];failedDrafts.clear();activityDirty=false;activity=S.clone(progress().activities[ui.stageId]||{});closeModal();navigate(screen,params,true);};return;
  }
  stopVideo();ui={...ui,screen,...params};render();window.scrollTo({top:0,behavior:'instant'});
}
function header(back=''){return `<header class="head">${back?`<div class="back-label">${button(icon('back'),ui.screen==='editor'?'editor-back':'go',back,'icon-btn','aria-label="رجوع"')}<span>${back==='journey'?journey().short:'الحياة الطيبة'}</span></div>`:`<div class="brand">${icon('door')}<span>الحياة الطيبة</span></div>`}<div class="head-actions">${S.data.characterId?button(doll(),'go','profile','icon-btn','aria-label="افتح شخصيتي"'):''}${button(icon('settings'),'go','settings','icon-btn','aria-label="الإعدادات"')}</div></header>`;}
function nav(active){return `<nav class="nav" aria-label="التنقل الرئيسي">${[['map','map','الخريطة'],['moments','leaf','لحظاتي'],['notebook','book','دفتر الرحلة']].map(([route,i,label])=>button(icon(i)+`<span>${label}</span>`,'go',route,'',active===route?'aria-current="page"':'')).join('')}</nav>`;}
function shell(html,{back='',tab='',cls=''}={}){return `${header(back)}<main class="content ${cls}" tabindex="-1">${html}</main>${tab?nav(tab):''}`;}
function quote(s){return s.quote?`<blockquote class="quote"><p>${s.quote.source.startsWith('حديث')?'«':'﴿'}${esc(s.quote.text)}${s.quote.source.startsWith('حديث')?'»':'﴾'}</p><cite>${esc(s.quote.source)}</cite></blockquote>`:'';}
function unlocked(j,s){const idx=j.stages.findIndex(x=>x.id===s.id);return idx===0 || S.data.journeys[j.id].completed.includes(j.stages[idx-1].id) || S.data.journeys[j.id].completed.includes(s.id);}
function nextStage(j){return j.stages.find(x=>!S.data.journeys[j.id].completed.includes(x.id))||j.stages[j.stages.length-1];}
function openJourney(id){if(!C.journeys.some(x=>x.id===id))return;if(!save(d=>d.activeJourneyId=id))return;navigate('journey',{jid:id});}
function openStage(id,forceReplay=false){const j=journey(),s=j.stages.find(x=>x.id===id);if(!s)return;
  if(!unlocked(j,s)){const prev=j.stages[j.stages.indexOf(s)-1];modal('خطوة بخطوة',`هذه المحطة تفتح بعد «${prev.title}».`,()=>{closeModal();openStage(prev.id);},'اذهب للمحطة السابقة');return;}
  const cp=progress().checkpoint;
  const step=s.video&&!progress().videos[s.video]?.completed?'video':cp?.stageId===id&&cp.step==='reflection'&&progress().activities[id]?.completed?'reflection':'activity';
  if(!save(d=>d.journeys[j.id].checkpoint={stageId:id,step}))return;
  activity=S.clone(progress().activities[id]||{});activityDirty=false;
  navigate(step==='video'?'video':step==='reflection'?'reflect':'stage',{stageId:id,step,segmentId:s.video,videoReturn:'stage'});
}
function updateActivity(key,value,renderNow=true){activity[key]=value;activityDirty=!S.commit(d=>d.journeys[ui.jid].activities[ui.stageId]=S.clone(activity));if(activityDirty)toast('اختيارك ما زال هنا، لكن لم يُحفظ بعد.');if(renderNow)render();}
function activityReady(s){
  if(s.type==='review')return true;
  if(s.type==='matching')return s.pairs.every((p,i)=>String(activity['match'+i])===String(i))&&Number.isInteger(activity.virtueChoice);
  if(s.type==='rewrite')return s.rewrites.every((p,i)=>!!activity['rewrite'+i]?.trim()||activity['example'+i]);
  if(s.type==='stories')return Number.isInteger(activity.story)&&activity.inspected;
  if(s.type==='plan')return !!(activity.virtue&&activity.behavior&&activity.good);
  return Number.isInteger(activity.selected);
}
function continueActivity(){const s=stage();if(!activityReady(s)){toast('جرّب التفاعل في هذه المحطة أولًا.');return;}
  if(!save(d=>{const j=d.journeys[ui.jid];j.activities[s.id]={...S.clone(activity),completed:true};j.checkpoint={stageId:s.id,step:'reflection'};if(s.id==='d3')j.plan={moment:s.options[activity.selected]};if(s.type==='matching'){const pair=s.pairs[activity.virtueChoice];j.plan={virtue:pair[1],behavior:pair[0],good:pair[1],review:'أراجع محاولتي برفق'};}if(s.type==='plan')j.plan={virtue:activity.virtue,behavior:activity.behavior,good:activity.good,review:'وقفة قصيرة آخر اليوم',createdAt:new Date().toISOString()};}))return;
  activityDirty=false;navigate('reflect',{step:'reflection'});
}
function finishStage(){const s=stage(),p=progress();if(!p.activities[s.id]?.completed&&!p.completed.includes(s.id)){toast('أكمل نشاط المحطة أولًا.');return;}
  if(s.video&&!p.videos[s.video]?.completed){openStage(s.id);return;}
  if(!save(d=>{const j=d.journeys[ui.jid];if(!j.completed.includes(s.id))j.completed.push(s.id);if(!j.badges.includes(s.id))j.badges.push(s.id);const next=journey().stages[journey().stages.indexOf(s)+1];j.checkpoint=next?{stageId:next.id,step:next.video?'video':'activity'}:null;}))return;
  navigate('reward');
}
function stageBody(){const s=stage(),p=progress(),i=journey().stages.indexOf(s);let html=`<div class="row spread"><span class="eyebrow">${esc(s.phase)}</span><span class="small">المحطة ${num(i+1)} من ${num(journey().stages.length)}</span></div><div class="stage-banner">${doll()}<div><h1>${esc(s.title)}</h1><span class="tag">${esc(journey().short)}</span></div></div><div class="panel ${journey().theme}"><p>${esc(s.story)}</p></div><h3>${esc(s.question)}</h3>`;
  if(['select','scenario','mission','mirror'].includes(s.type)){
    html+=`<div class="choice-list">${s.options.map((o,n)=>button(`<span class="dot"></span><span>${esc(typeof o==='string'?o:o.label)}</span>`,'choose',n,'choice',`aria-pressed="${activity.selected===n}"`)).join('')}</div>`;
    if(Number.isInteger(activity.selected)&&s.type==='scenario')html+=`<div class="feedback" role="status">${esc(s.options[activity.selected].feedback)}</div>${button('أجرّب اختيارًا آخر','retry-choice','','quiet')}`;
  }
  if(s.type==='stories'){
    html+=`<div class="chips">${s.stories.map((o,n)=>button(esc(o.title),'story',n,'chip',`aria-pressed="${activity.story===n}"`)).join('')}</div>`;
    if(Number.isInteger(activity.story)){const x=s.stories[activity.story];html+=`<div class="panel pink"><p>${esc(x.text)}</p></div><p class="small">فكّر: ما السلوك الخاطئ؟ من تأذّى؟ وما التصرف الأفضل؟</p>`;
      html+=activity.inspected?`<div class="feedback"><p><strong>السلوك:</strong> ${esc(x.wrong)}</p><p><strong>من تأذّى:</strong> ${esc(x.hurt)}</p><p><strong>خطوة أفضل:</strong> ${esc(x.better)}</p></div>`:button('أفكر ثم أكتشف','inspect-story','','secondary');
    }
  }
  if(s.type==='matching')html+=`<div>${s.pairs.map((p,n)=>`<div class="match-card"><label for="match${n}">${esc(p[0])}</label><select id="match${n}" data-field="match${n}"><option value="">اختر خطوة تساعد</option>${[2,0,4,1,3].map(k=>`<option value="${k}" ${String(activity['match'+n])===String(k)?'selected':''}>${esc(s.pairs[k][1])}</option>`).join('')}</select>${activity['match'+n]!==undefined?`<div class="small">${String(activity['match'+n])===String(n)?'هذه خطوة تساعد على هذا السلوك.':'جرّب خطوة أخرى تناسب هذا السلوك.'}</div>`:''}</div>`).join('')}</div><div class="gap"></div><h3>أي خطوة أحب أن أجربها؟</h3><div class="choice-list">${s.pairs.map((p,n)=>button(esc(p[1]),'virtue-choice',n,'choice',`aria-pressed="${activity.virtueChoice===n}"`)).join('')}</div><p class="small">سنحتفظ بها في «لحظاتي». تطبيقها خارج الشاشة اختياري.</p>`;
  if(s.type==='rewrite')html+=`<div class="rewrites">${s.rewrites.map((r,n)=>`<div class="rewrite-card"><label for="rewrite${n}">«${esc(r.text)}»</label><textarea id="rewrite${n}" data-field="rewrite${n}" maxlength="500" placeholder="عبارة محترمة وواضحة">${esc(activity['rewrite'+n]||'')}</textarea>${button('أتأمل مثالًا','example',n,'quiet')}${activity['example'+n]?`<div class="feedback">${esc(r.example)}</div>`:''}</div>`).join('')}</div>`;
  if(s.type==='review')html+=s.prompts.map((p,n)=>`<div class="prompt-row"><span>${esc(p)}</span>${button('أكتب','open-prompt',n,'secondary')}</div>`).join('')+'<p class="small">يمكنك التفكير دون كتابة ثم المتابعة.</p>';
  if(s.type==='plan')html+=`<div class="field"><label for="virtue">خلق أنمّيه</label><select id="virtue" data-field="virtue"><option value="">اختر خلقًا</option>${['الصدق','الرحمة','الصبر','الكلمة الطيبة','التسامح'].map(x=>`<option ${activity.virtue===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="behavior">سلوك أحاول تغييره</label><select id="behavior" data-field="behavior"><option value="">اختر سلوكًا</option>${['الكذب','الكلام المؤذي','الأنانية','السخرية','سوء الظن'].map(x=>`<option ${activity.behavior===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="good">عمل خير يومي</label><select id="good" data-field="good"><option value="">اختر خطوة صغيرة</option>${['مساعدة أحد','كلمة طيبة','الاستماع باهتمام','الترحيب بزميل'].map(x=>`<option ${activity.good===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="panel leaf"><p>وقفة قصيرة آخر اليوم: ماذا جرّبت؟ وماذا سأحاول غدًا؟</p><p class="small">الخطة لسبعة أيام، ويمكنك الاستمرار بعدها. لا يشترط انتظار الأيام لإكمال الرحلة.</p></div>`;
  html+=quote(s)+`<p>${esc(s.lesson)}</p>`;
  if(s.replay)html+=button('أعيد فيديو البداية','replay-segment',s.replay,'quiet');
  html+=`<div class="actions">${button(s.type==='review'?'تأملت… نكمل':'نكمل المحطة','activity-next','','primary',activityReady(s)?'':'disabled')}${button('رجوع لخريطة الرحلة','go','journey','quiet')}</div>`;
  return shell(html,{back:'journey'});
}
function reflectionId(index){return `${ui.jid}:${ui.stageId}:p${index}`;}
function getDraft(id){return Object.hasOwn(draftCache,id)?draftCache[id]:S.data.drafts[id]??S.data.reflections[id]?.text??'';}
function openPrompt(index){const s=stage();if(!s?.prompts?.[index])return;navigate('editor',{promptId:reflectionId(index),promptTitle:s.prompts[index],returnTo:{screen:ui.screen,jid:ui.jid,stageId:ui.stageId}});}
function returnFromEditor(){const target=ui.returnTo||{screen:'notebook'};navigate(target.screen,target);}
function saveReflection(){const id=ui.promptId,text=getDraft(id).trim();if(!text){toast('اكتب ما تحب، أو تابع من غير كتابة.');return;}
  if(!save(d=>{d.drafts[id]=getDraft(id);d.reflections[id]={text,journeyId:ui.jid,stageId:ui.stageId,promptId:id,title:ui.promptTitle,updatedAt:new Date().toISOString()};}))return;
  failedDrafts.delete(id);toast('تم حفظ التأمل على هذا الجهاز.');returnFromEditor();
}
function deleteEntry(id){modal('تمسح هذه الكتابة؟','سيُمسح التأمل ومسودته فقط. تقدم الرحلة يظل محفوظًا.',()=>{if(S.deleteWriting(id)){delete draftCache[id];failedDrafts.delete(id);closeModal();navigate('notebook',{},true);toast('تم مسح الكتابة.');}else toast('لم نقدر نمسح الكتابة. ما زالت محفوظة.');},'امسح الكتابة');}
function editorBody(){const text=getDraft(ui.promptId);return shell(`<span class="eyebrow">دفتر الرحلة · ${esc(journey()?.short||'الذكر')}</span><h1>مساحة لك</h1><p>${esc(ui.promptTitle)}</p><label class="small" for="reflection">تأملك المكتوب · اختياري</label><textarea id="reflection" maxlength="2000" placeholder="اكتب ما تحب أن تتذكره…">${esc(text)}</textarea><div id="draft-status" class="editor-status ${failedDrafts.has(ui.promptId)?'error':''}">${failedDrafts.has(ui.promptId)?'تعذر الحفظ. كتابتك ما زالت هنا.':S.data.drafts[ui.promptId]!==undefined?'المسودة محفوظة على الجهاز':'كتابتك خاصة، وتُحفظ على هذا الجهاز فقط.'}</div><div class="small" id="count">${num(text.length)} / ٢٠٠٠</div><div class="actions">${button('احفظ التأمل','save-reflection')}${button('أرجع من غير حفظ تأمل','editor-back','','secondary')}${S.data.reflections[ui.promptId]||S.data.drafts[ui.promptId]?button('امسح هذه الكتابة','delete-entry',ui.promptId,'quiet danger'):''}</div>`,{back:ui.returnTo?.screen==='notebook'?'notebook':'journey'});}
function notebookBody(){const ids=[...new Set([...Object.keys(S.data.reflections),...Object.keys(S.data.drafts)])].filter(id=>!id.startsWith('activity:')&&(S.data.reflections[id]?.text||S.data.drafts[id]?.trim()));return shell(`<div class="notebook-title"><span class="eyebrow">أفكار أعود إليها</span><h1>دفتر الرحلة</h1><p class="small">خاص بك على هذا الجهاز. يمكنك الكتابة أو الاكتفاء بالتفكير.</p></div>${ids.length?ids.map(id=>{const r=S.data.reflections[id],jid=r?.journeyId||id.split(':')[0],j=C.journeys.find(x=>x.id===jid)||C.journeys[0],s=j.stages.find(x=>x.id===r?.stageId||x.id===id.split(':')[1]),title=r?.title||s?.prompts?.[Number(id.split(':')[2]?.slice(1))]||'تأمل من الذكر';return button(`<span class="tag">${j.short} · ${esc(s?.title||'من رحلتك السابقة')}</span><h3>${esc(title)}</h3><p>${esc((S.data.drafts[id]??r?.text??'').slice(0,100))}</p><span class="small">${r?'تأمل محفوظ':'مسودة'}${r?.updatedAt?' · '+date(r.updatedAt):''}</span>`,'entry',id,'journal-entry');}).join(''):`<div class="empty">${icon('book')}<h3>دفترك ينتظر أفكارك</h3><p>تقدر تكتب عندما تحب، دون أن يؤثر ذلك على تقدمك.</p></div>`}<div class="actions">${button('أختار محطة وأتأمل','go','map','secondary')}</div>`,{tab:'notebook'});}
function momentsBody(){const p=progress(),j=journey(),plan=p.plan;return shell(`<span class="eyebrow">محاولات صغيرة… كل يوم</span><h1>لحظاتي</h1><div class="chips">${C.journeys.map(x=>button(x.short,'moment-journey',x.id,'chip',`aria-pressed="${ui.jid===x.id}"`)).join('')}</div>${plan?`<div class="panel ${j.theme}"><h3>خطتي في ${j.short}</h3>${plan.virtue?`<p>أنمّي ${esc(plan.virtue)}، وأحاول تغيير ${esc(plan.behavior)}.</p><p>عمل الخير: ${esc(plan.good)}</p><p class="small">${esc(plan.review)}</p>`:`<p>لحظتي: ${esc(({sleep:'قبل النوم',study:'قبل المذاكرة',walk:'أثناء المشي',happy:'عندما أفرح',hard:'في موقف صعب',wake:'بعد الاستيقاظ'})[plan.moment]||plan.moment)}</p>`}</div><h3>${j.id==='tazkiya'?'دعوة لسبعة أيام':'محاولتي اليوم'}</h3><p class="small">كل محاولة محفوظة. إذا فاتك يوم، ارجع عندما تستطيع.</p><div class="days">${Array.from({length:7},(_,n)=>`<span class="day ${n<p.practice.length?'filled':''}" aria-label="${n<p.practice.length?'محاولة مسجلة':'مساحة لمحاولة'} ${num(n+1)}">${n<p.practice.length?'✓':num(n+1)}</span>`).join('')}</div><div class="choice-list">${['جربت خطوتي اليوم','حاولت وأحتاج أن أجرب ثانية','لم أجرب بعد'].map(x=>button(esc(x),'practice',x,'choice')).join('')}</div>${button('أعدّل خطتي','plan-edit',j.id,'quiet')}<h3>محاولاتي السابقة</h3>${p.practice.length?p.practice.slice().reverse().map(x=>`<div class="prompt-row"><span>${esc(x.text)}</span><span class="small">${esc(x.date||x.day)}</span></div>`).join(''):'<p class="small">لم تسجل محاولة بعد.</p>'}`:`<div class="empty">${icon('leaf')}<p>اختر خطوة من رحلتك، ثم عُد لتسجيل محاولة عندما تحب.</p></div>${button('أستكشف الرحلة','journey',j.id)}`}`,{tab:'moments'});}
function checkIn(text,confirmed=false){const today=day(),p=progress(),existing=p.practice.findIndex(x=>x.day===today);if(existing>=0&&!confirmed){modal('لديك تسجيل لهذا اليوم','هل تحب تعديل تسجيل اليوم؟ محاولات الأيام الأخرى ستبقى محفوظة.',()=>{closeModal();checkIn(text,true);},'عدّل تسجيل اليوم');return;}
  if(save(d=>{const a=d.journeys[ui.jid].practice,entry={day:today,date:date(new Date()),text};if(existing>=0)a[existing]=entry;else a.push(entry);})){render();toast('تم تسجيل محاولتك. يمكنك العودة في أي وقت.');}
}
function render(){root.className='app '+(S.data.settings.motion?'':'reduced');let html='';const j=journey();
  if(ui.screen==='load-error')html=shell(`<h1>لم نقدر نفتح تقدمك</h1><p>بياناتك القديمة لم تُستبدل. حاول إعادة فتح الصفحة.</p><div class="actions">${button('إعادة المحاولة','reload')}${button('الإعدادات','go','settings','secondary')}</div>`);
  if(ui.screen==='welcome')html=shell(`<span class="eyebrow center" style="display:block">خطوة صغيرة إلى خير أكبر</span><div class="wood-plaque"><h1>الحياة الطيبة</h1><p style="margin:4px 0">رحلتك تبدأ من هنا</p></div>${hero(true)}<h2>اكتشف أبواب الخير</h2><p>حكايات ومواقف تشبه يومك. اختر شخصيتك، وابدأ رحلة الذكر أو التزكية على راحتك.</p><div class="actions">${button('ابدأ رحلتك '+icon('arrow'),'go','character')}</div><p class="small center">للأعمار ١٠–١٤ · لا تحتاج إلى حساب</p>`,{cls:'welcome'});
  if(ui.screen==='character')html=shell(`<span class="eyebrow">أنت بطل الرحلة</span><h1>اختر شخصيتك</h1><p>نفس رفيق الرحلة في كل الأبواب. تقدر تغيره بعدين وتقدمك يفضل محفوظًا.</p>${S.data.legacy&&!S.data.characterId?'<div class="panel leaf"><p>تقدمك وكتاباتك السابقة محفوظة. اختر واحدة من الشخصيتين الجديدتين لنكمل.</p></div>':''}<div class="character-grid">${C.characters.map(c=>button(`<img src="${c.asset}" alt="${esc(c.label)}"><strong>${c.label}</strong>`,'character',c.id,'character-card',`aria-pressed="${selectedCharacter===c.id}"`)).join('')}</div><div class="field"><label for="nickname">اسم تحب نناديك به <span class="small">(اختياري)</span></label><input id="nickname" maxlength="24" autocomplete="off" value="${esc(nickname)}" placeholder="مستكشف الحياة الطيبة"></div><div class="actions">${button('هذه شخصيتي '+icon('arrow'),'save-character','','primary',selectedCharacter?'':'disabled')}${S.data.characterId?button('رجوع','go','profile','quiet'):''}</div>`,{back:S.data.characterId?'profile':'welcome'});
  if(ui.screen==='map'){const active=C.journeys.find(x=>x.id===S.data.activeJourneyId),cp=S.data.journeys[active.id].checkpoint;html=shell(`<div class="map-header"><div><span class="eyebrow">أهلًا ${esc(S.data.profile?.name||'يا مستكشف')}</span><h1>خريطة الحياة الطيبة</h1></div>${doll()}</div><p class="small">اختر بابك. كل رحلة لها خطواتها، ويمكنك العودة إليها في أي وقت.</p>${cp?`<div class="resume"><div style="flex:1"><h3>نكمل من حيث وقفنا؟</h3><span class="small">${active.short} · ${esc(active.stages.find(x=>x.id===cp.stageId)?.title||'رحلتك')}</span></div>${button('نكمل','resume',active.id)}</div>`:''}<div class="map-world">${garden()}<div class="world-title">بابان مفتوحان لبداية جديدة</div>${C.journeys.map(x=>{const n=S.data.journeys[x.id].completed.length;return button(`${doorArt(x.theme)}<div class="door-details"><h3>${esc(x.title)}</h3><p class="small">${esc(x.subtitle)}</p><span class="tag">${n?num(n)+' محطات اكتشفتها':'ابدأ من هنا'}</span></div>${icon('arrow')}`,'journey',x.id,'door-button');}).join('')}</div><p class="small center">المحاولة والتعلّم أهم من الكمال.</p>`,{tab:'map'});}
  if(ui.screen==='journey'){const p=progress(),next=nextStage(j);let phase='';html=shell(`<span class="eyebrow">${esc(j.scope)}</span><h1>${esc(j.title)}</h1><p>${esc(j.intro)}</p><div class="row spread"><span class="small">${num(p.completed.length)} من ${num(j.stages.length)} محطات</span><span class="tag">خطوة بخطوة</span></div><div class="progress"><span style="width:${p.completed.length/j.stages.length*100}%"></span></div>${button(p.completed.length===j.stages.length?'أعود إلى الرحلة':p.completed.length?'أكمل رحلتي':'أبدأ المغامرة','stage',next.id)}<div class="trail">${j.stages.map((s,i)=>{const done=p.completed.includes(s.id),open=unlocked(j,s);let title='';if(s.phase!==phase){phase=s.phase;title=`<div class="phase-title">${esc(phase)}</div>`;}return title+button(`<span class="number">${done?icon('check'):open?num(i+1):icon('lock')}</span><div><h3>${esc(s.title)}</h3><p class="small">${done?'اكتشفتها · أعد الزيارة':open?s.video&&!p.videos[s.video]?.completed?'فيديو قصير ثم نشاط':'جاهزة للاكتشاف':'تفتح بعد المحطة السابقة'}</p></div>`,'stage',s.id,`stage-row ${done?'done':open?'current':'locked'}`);}).join('')}</div>`,{back:'map'});}
  if(ui.screen==='stage')html=stageBody();
  if(ui.screen==='reflect'){const s=stage();html=shell(`<span class="eyebrow">وقفة على راحتك</span><h1>ما الذي اكتشفته؟</h1><p>يمكنك كتابة فكرة في دفترك، أو التفكير فيها ثم المتابعة. لا توجد إجابة نقيس بها مشاعرك.</p>${s.prompts.map((p,n)=>`<div class="prompt-row"><span>${esc(p)}</span>${button(S.data.reflections[reflectionId(n)]?'أعدّل':S.data.drafts[reflectionId(n)]?'مسودتي':'أكتب','open-prompt',n,'secondary')}</div>`).join('')}<div class="actions">${button('أكمل المحطة','finish-stage')}${button('أراجع النشاط','go','stage','quiet')}</div>`,{back:'journey'});}
  if(ui.screen==='editor')html=editorBody();
  if(ui.screen==='notebook')html=notebookBody();
  if(ui.screen==='moments')html=momentsBody();
  if(ui.screen==='reward'){const s=stage(),last=j.stages.indexOf(s)===j.stages.length-1;html=shell(`<div class="center"><span class="eyebrow">${last?'اكتملت رحلة التعلّم':'خطوة اكتشفتها'}</span><div class="badge-art">${icon(last?'heart':'leaf')}</div><h1>${esc(s.badge)}</h1><p>${last?esc(j.id==='tazkiya'?s.lesson:'انتهت الجلسة الافتتاحية من رحلة الذكر. يمكنك العودة إلى ما تعلمته.'):'تذكار مشاركتك في «'+esc(s.title)+'».'}</p><p class="small">شارة تعلّم ومحاولة؛ لا تقيس صلاح القلب أو تقارنك بغيرك.</p></div>${hero()}<div class="actions">${button(last?'أعود للحظاتي':'المحطة التالية '+icon('arrow'),last?'go':'stage',last?'moments':j.stages[j.stages.indexOf(s)+1].id)}${button('خريطة الرحلة','go','journey','secondary')}</div>`,{back:'journey',cls:'reward'});}
  if(ui.screen==='profile'){const badges=C.journeys.flatMap(x=>x.stages.filter(s=>S.data.journeys[x.id].badges.includes(s.id)).map(s=>({j:x,s})));html=shell(`<span class="eyebrow">رفيق كل الأبواب</span><h1>${esc(S.data.profile?.name||'شخصيتي')}</h1>${hero()}${button('أغيّر الشخصية أو الاسم','edit-character','','secondary')}<div class="gap"></div><h2>تذكارات رحلتي</h2>${badges.length?`<div class="badge-grid">${badges.map(({j,s})=>`<div class="badge-card">${icon('leaf')}<div>${esc(s.badge)}</div><span class="small">${esc(j.short)}</span></div>`).join('')}</div>`:'<p>أول تذكارك في نهاية أول محطة.</p>'}<p class="small">هذه تذكارات لما تعلمته، وليست تقييمًا لك.</p>`,{back:'map'});}
  if(ui.screen==='settings')html=shell(`<span class="eyebrow">على راحتك</span><h1>تجربتك وبياناتك</h1><div class="settings-row"><div><p>لغة الرحلة</p><span class="small">العربية الآن، والإنجليزية لاحقًا</span></div><span class="tag">العربية</span></div>${button(`<div><p>تقليل الحركة</p><span class="small">شاشة أهدأ عندما تحب</span></div><span class="switch ${S.data.settings.motion?'':'on'}"></span>`,'motion','','settings-row',`role="switch" aria-checked="${!S.data.settings.motion}"`)}<div class="panel sky"><h3>محفوظ على هذا الجهاز</h3><p>الشخصية والتقدم والكتابات خاصة بهذا المتصفح. مسح بياناته أو تغيير الجهاز قد يفقدها، ولا توجد نسخة سحابية.</p><p class="small">هذه معاينة ويب؛ فتحها والفيديو لأول مرة يحتاج إنترنت. النسخة المثبتة المخطط لها ستضم المحتوى للعمل دون إنترنت.</p></div><div class="actions">${button('امسح بياناتي وابدأ من جديد','reset','','secondary danger')}</div><p class="small center">الحياة الطيبة · معاينة ٠٫٥</p>`,{back:S.loadError?'load-error':S.data.characterId?'map':'welcome'});
  if(ui.screen==='video')html=videoBody();
  root.innerHTML=html;
  if(ui.screen==='video')initVideo();
}
function videoBody(){const seg=C.segments[ui.segmentId],stored=progress().videos[seg.id];return shell(`<span class="eyebrow">قبل ${esc(stage().title)}</span><h1>${esc(seg.title)}</h1><p class="small">جزء قصير من فيلم الرحلة. تقدر توقفه وتكمل من نفس المكان.</p><div class="video-wrap"><video id="journey-video" playsinline preload="metadata" aria-label="${esc(seg.title)}" src="assets/tazkiya-overview.mp4"></video><div id="video-error" class="video-error" hidden><h3>لم نقدر نفتح الفيديو</h3><p>حاول فتحه مرة أخرى. تقدمك السابق محفوظ.</p>${button('إعادة المحاولة','video-retry','','secondary')}</div></div><div class="video-controls"><div class="row">${button(icon('play')+'<span>تشغيل</span>','video-play','','', 'id="play-button" aria-label="تشغيل الفيديو"')}${button('من البداية','video-restart','','')}${button('كتم الصوت','video-mute','','','id="mute-button"')}</div><label for="video-seek" class="small">موضعك داخل هذا الجزء</label><input id="video-seek" type="range" min="0" max="1" step="0.1" value="0" aria-label="موضع الفيديو داخل الجزء"><div class="row"><span id="video-status" class="small" role="status">جارٍ تجهيز الفيديو…</span><span id="video-time" class="time">0:00 / —</span></div></div><details class="panel leaf"><summary>الفكرة في كلمات</summary><p>${esc(seg.description)}</p><p class="small">ملخص للفكرة، وليس تفريغًا حرفيًا لكل كلام الفيديو.</p></details><div class="actions">${button(ui.videoReturn==='stage-replay'?'أرجع للنشاط':'أدخل المحطة '+icon('arrow'),'video-next','','primary',stored?.completed?'':'disabled')}${button('رجوع لخريطة الرحلة','go','journey','quiet')}</div>`,{back:'journey'});}
function clock(seconds){return Math.floor(seconds/60)+':'+String(Math.floor(seconds%60)).padStart(2,'0');}
function videoRecord(complete=false){if(!videoReady||!video||mediaFailed)return false;const seg=C.segments[ui.segmentId],position=Math.max(seg.start,Math.min(videoEnd,video.currentTime));return S.commit(d=>{const j=d.journeys[ui.jid],old=j.videos[seg.id];j.videos[seg.id]={videoSegmentId:seg.id,position,completed:!!(old?.completed||complete)};});}
function completeVideo(){if(videoComplete||mediaFailed)return;video.pause();video.currentTime=videoEnd;videoComplete=true;if(videoRecord(true)){const b=root.querySelector('[data-act="video-next"]');if(b)b.disabled=false;setVideoStatus('اكتمل هذا الجزء. يمكنك دخول المحطة.');}else{videoComplete=false;setVideoStatus('اكتمل العرض، لكن لم يُحفظ. جرّب الحفظ مرة أخرى.');toast('تقدم الفيديو لم يُحفظ. اضغط تشغيل لإعادة محاولة الحفظ.');}}
function setVideoStatus(text){const el=document.getElementById('video-status');if(el)el.textContent=text;}
function updateVideo(){if(!videoReady||!video)return;const seg=C.segments[ui.segmentId],pos=video.currentTime;
  if(pos<seg.start-.02||pos>videoEnd+.05){video.currentTime=Math.max(seg.start,Math.min(videoEnd-.05,pos));return;}
  if(!video.seeking&&!video.paused&&pos>=videoEnd-.045){completeVideo();return;}
  const range=document.getElementById('video-seek'),time=document.getElementById('video-time');if(range)range.value=Math.max(0,pos-seg.start);if(time)time.textContent=clock(Math.max(0,pos-seg.start))+' / '+clock(videoEnd-seg.start);
  if(!video.paused&&Math.abs(pos-lastMediaSave)>=2){lastMediaSave=pos;if(!videoRecord())setVideoStatus('التشغيل مستمر؛ تعذر حفظ موضعك.');}
  lastObserved=pos;
}
function frameWatch(_,metadata){if(!video)return;if(metadata.mediaTime>=videoEnd-.045&&!video.paused&&!video.seeking)completeVideo();else updateVideo();if(video&&!video.paused&&video.requestVideoFrameCallback)frameId=video.requestVideoFrameCallback(frameWatch);}
function initVideo(){video=document.getElementById('journey-video');videoReady=false;videoComplete=false;mediaFailed=false;const seg=C.segments[ui.segmentId];
  video.addEventListener('loadedmetadata',()=>{videoEnd=seg.end??video.duration;if(!Number.isFinite(videoEnd)||video.duration<videoEnd-.1){failVideo();return;}videoReady=true;const saved=progress().videos[seg.id];video.currentTime=Math.max(seg.start,Math.min(videoEnd-.1,Number(saved?.position)||seg.start));lastMediaSave=video.currentTime;document.getElementById('video-seek').max=videoEnd-seg.start-.05;setVideoStatus(saved?.completed?'هذا الجزء مكتمل؛ يمكنك إعادته.':'جاهز عندما تحب.');updateVideo();});
  video.addEventListener('error',failVideo);video.addEventListener('timeupdate',updateVideo);
  video.addEventListener('seeking',()=>{if(videoReady){const clamped=Math.max(seg.start,Math.min(videoComplete?videoEnd:videoEnd-.05,video.currentTime));if(Math.abs(clamped-video.currentTime)>.01)video.currentTime=clamped;}});
  video.addEventListener('play',()=>{mediaWasPlaying=true;const b=document.getElementById('play-button');if(b){b.innerHTML=icon('pause')+'<span>إيقاف</span>';b.setAttribute('aria-label','إيقاف الفيديو');}setVideoStatus('يمكنك الإيقاف والعودة عندما تحب.');if(video.requestVideoFrameCallback)frameId=video.requestVideoFrameCallback(frameWatch);});
  video.addEventListener('pause',()=>{const b=document.getElementById('play-button');if(b){b.innerHTML=icon('play')+'<span>تشغيل</span>';b.setAttribute('aria-label','تشغيل الفيديو');}if(mediaWasPlaying&&!mediaFailed&&!videoRecord(videoComplete))setVideoStatus('الموضع لم يُحفظ. جرّب مرة أخرى.');});
  video.addEventListener('ended',()=>{if(videoReady&&videoEnd===video.duration)completeVideo();});
}
function failVideo(){if(!video||ui.screen!=='video')return;mediaFailed=true;videoReady=false;const error=document.getElementById('video-error');if(error)error.hidden=false;setVideoStatus('الفيديو غير متاح.');const next=root.querySelector('[data-act="video-next"]');if(next)next.disabled=true;}
function stopVideo(){if(video){video.pause();if(videoReady&&!mediaFailed&&!videoRecord(videoComplete))toast('تعذر حفظ آخر موضع للفيديو. موضعك المحفوظ السابق ما زال موجودًا.');if(frameId&&video.cancelVideoFrameCallback)video.cancelVideoFrameCallback(frameId);video.removeAttribute('src');video.load();video=null;}videoReady=false;mediaWasPlaying=false;}
root.addEventListener('click',async event=>{const target=event.target.closest('[data-act]');if(!target||target.disabled)return;const act=target.dataset.act,value=target.dataset.value;
  if(act==='go'){if(!S.data.characterId&&!['welcome','character','settings','load-error'].includes(value)){navigate('character');return;}navigate(value);}
  if(act==='character'){nickname=document.getElementById('nickname').value;selectedCharacter=value;render();}
  if(act==='save-character'){nickname=document.getElementById('nickname').value.trim();if(!selectedCharacter)return;if(save(d=>{d.characterId=selectedCharacter;d.profile={name:nickname};}))navigate('map');}
  if(act==='edit-character'){selectedCharacter=S.data.characterId;nickname=S.data.profile?.name||'';navigate('character');}
  if(act==='journey')openJourney(value);
  if(act==='resume'){if(save(d=>d.activeJourneyId=value)){ui.jid=value;openStage(progress().checkpoint?.stageId||nextStage(journey()).id);}}
  if(act==='stage')openStage(value);
  if(act==='choose')updateActivity('selected',Number(value));
  if(act==='virtue-choice')updateActivity('virtueChoice',Number(value));
  if(act==='retry-choice')updateActivity('selected',null);
  if(act==='story'){activity.inspected=false;updateActivity('story',Number(value));}
  if(act==='inspect-story')updateActivity('inspected',true);
  if(act==='example')updateActivity('example'+value,true);
  if(act==='activity-next')continueActivity();
  if(act==='finish-stage')finishStage();
  if(act==='open-prompt')openPrompt(Number(value));
  if(act==='save-reflection')saveReflection();
  if(act==='editor-back')returnFromEditor();
  if(act==='delete-entry')deleteEntry(value);
  if(act==='entry'){const r=S.data.reflections[value],parts=value.split(':'),jid=r?.journeyId||(['dhikr','tazkiya'].includes(parts[0])?parts[0]:'dhikr'),sid=r?.stageId||parts[1]||'d4',s=C.journeys.find(x=>x.id===jid).stages.find(x=>x.id===sid);navigate('editor',{jid,stageId:s?.id||'d4',promptId:value,promptTitle:r?.title||s?.prompts[Number(parts[2]?.slice(1))]||'تأمل من رحلة الذكر السابقة',returnTo:{screen:'notebook'}});}
  if(act==='moment-journey'){if(save(d=>d.activeJourneyId=value))navigate('moments',{jid:value});}
  if(act==='practice')checkIn(value);
  if(act==='plan-edit'){const sid=value==='tazkiya'?'t12':'d3';if(unlocked(journey(),journey().stages.find(x=>x.id===sid)))openStage(sid);else openJourney(value);}
  if(act==='motion'){if(save(d=>d.settings.motion=!d.settings.motion))render();}
  if(act==='reset')modal('تبدأ من جديد؟','سيُمسح اختيار الشخصية وتقدم الرحلتين والخطط وكل الكتابات من هذا المتصفح. لا يمكن التراجع.',()=>{if(S.reset()){failedDrafts.clear();Object.keys(draftCache).forEach(k=>delete draftCache[k]);activityDirty=false;selectedCharacter=null;nickname='';closeModal();navigate('welcome',{},true);}else toast('لم نقدر نمسح البيانات. بياناتك ما زالت محفوظة.');},'امسح بياناتي');
  if(act==='reload')location.reload();
  if(act==='replay-segment'){const seg=C.segments[value];navigate('video',{segmentId:value,videoReturn:'stage-replay'});}
  if(act==='video-retry'){stopVideo();render();}
  if(act==='video-play'&&videoReady){if(video.currentTime>=videoEnd-.06&&!videoComplete){completeVideo();return;}if(video.paused){if(videoComplete){video.currentTime=C.segments[ui.segmentId].start;videoComplete=false;}try{await video.play();}catch(e){setVideoStatus('اضغط تشغيل للمحاولة مرة أخرى.');}}else video.pause();}
  if(act==='video-restart'&&videoReady){video.pause();video.currentTime=C.segments[ui.segmentId].start;videoComplete=false;videoRecord();setVideoStatus('جاهز من البداية. تقدمك السابق محفوظ.');updateVideo();}
  if(act==='video-mute'&&video){video.muted=!video.muted;target.textContent=video.muted?'تشغيل الصوت':'كتم الصوت';}
  if(act==='video-next'){if(!progress().videos[ui.segmentId]?.completed||mediaFailed)return;const returnTo=ui.videoReturn;if(save(d=>d.journeys[ui.jid].checkpoint={stageId:ui.stageId,step:'activity'}))navigate('stage',{videoReturn:null});}
});
root.addEventListener('input',event=>{const t=event.target;
  if(t.id==='nickname')nickname=t.value;
  if(t.id==='reflection'){draftCache[ui.promptId]=t.value;const ok=S.commit(d=>d.drafts[ui.promptId]=t.value);if(ok)failedDrafts.delete(ui.promptId);else failedDrafts.add(ui.promptId);const status=document.getElementById('draft-status');status.textContent=ok?'المسودة محفوظة على الجهاز':'تعذر الحفظ. كتابتك ما زالت هنا؛ جرّب حفظ التأمل مرة أخرى.';status.classList.toggle('error',!ok);document.getElementById('count').textContent=num(t.value.length)+' / ٢٠٠٠';}
  if(t.tagName==='TEXTAREA'&&t.dataset.field){updateActivity(t.dataset.field,t.value,false);const b=root.querySelector('[data-act="activity-next"]');if(b)b.disabled=!activityReady(stage());}
  if(t.id==='video-seek'&&videoReady){video.currentTime=C.segments[ui.segmentId].start+Number(t.value);videoComplete=false;updateVideo();}
});
root.addEventListener('change',event=>{const t=event.target;if(t.tagName==='SELECT'&&t.dataset.field)updateActivity(t.dataset.field,t.value);});
document.getElementById('dialog').addEventListener('click',event=>{const b=event.target.closest('[data-act]');if(!b)return;if(b.dataset.act==='close-dialog')closeModal();if(b.dataset.act==='confirm')document.getElementById('dialog').confirmAction?.();if(b.dataset.act==='discard-edits')document.getElementById('dialog').discardAction?.();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&video)video.pause();});
window.addEventListener('beforeunload',event=>{if(failedDrafts.size||activityDirty){event.preventDefault();event.returnValue='';}if(videoReady)videoRecord();});
// Read-only diagnostics for QA; normal entry paths still enforce learning prerequisites.
window.HayahApp={get screen(){return ui.screen;},get route(){return {...ui};},get content(){return C;}};
render();if(S.error==='migration-save')toast('تقدمك القديم موجود. تعذر حفظ التحديث الآن؛ جرّب مرة أخرى.');
})();
